<?php
require_once __DIR__ . '/includes/bootstrap.php';
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT) ?: 0;
$recipe = $id ? Recipe::find($id) : null;
if (!$recipe) { http_response_code(404); exit('Recipe not found.'); }
$pageTitle = $recipe['title'];
$ingredients = Recipe::ingredients($id); $comments = Comment::forRecipe($id); $isFavorite = Auth::check() && Favorite::exists(Auth::id(), $id); $isOwner = Auth::check() && (int) $recipe['user_id'] === Auth::id();
require __DIR__ . '/includes/header.php';
?>
<section class="container page-section detail-layout"><article class="recipe-detail"><div class="detail-kicker"><span><?= e($recipe['category_name']) ?></span><span><?= date('M j, Y', strtotime($recipe['created_at'])) ?><?php if ($recipe['updated_at'] > $recipe['created_at']): ?> · edited<?php endif; ?></span></div><h1><?= e($recipe['title']) ?></h1><p class="detail-description"><?= e($recipe['short_description']) ?></p><p class="byline">Shared by <strong><?= e($recipe['author_name']) ?></strong></p><div class="detail-actions"><a class="outline-button" href="<?= BASE_URL ?>/recipe_print.php?id=<?= $id ?>">Print recipe</a><?php if (Auth::check()): ?><button class="favorite-button <?= $isFavorite ? 'is-favorite' : '' ?>" data-favorite-id="<?= $id ?>" data-favorite-state="<?= $isFavorite ? 'saved' : 'unsaved' ?>"><?= $isFavorite ? '★ Saved' : '☆ Save favorite' ?></button><?php endif; ?><?php if ($isOwner): ?><a class="text-link" href="<?= BASE_URL ?>/recipe_edit.php?id=<?= $id ?>">Edit</a><form method="post" action="<?= BASE_URL ?>/recipe_delete.php" class="inline-form" data-confirm="Delete this recipe permanently?"><?= csrfField() ?><input type="hidden" name="id" value="<?= $id ?>"><button class="danger-link" type="submit">Delete</button></form><?php endif; ?></div><div class="detail-rule"></div><div class="recipe-columns"><section><h2>Ingredients</h2><ul class="ingredient-list"><?php foreach ($ingredients as $ingredient): ?><li><span><?= e($ingredient['quantity']) ?> <?= e($ingredient['unit']) ?></span><strong><?= e($ingredient['ingredient_name']) ?></strong></li><?php endforeach; ?></ul></section><section><h2>Instructions</h2><div class="instructions"><?= nl2br(e($recipe['instructions'])) ?></div></section></div></article><aside class="comments-panel"><div class="section-heading"><div><p class="eyebrow">From the kitchen</p><h2>Neighbor notes</h2></div><span class="comment-count"><?= count($comments) ?></span></div><?php if (Auth::check()): ?><form class="comment-form" method="post" action="<?= BASE_URL ?>/actions/comment_add.php"><input type="hidden" name="recipe_id" value="<?= $id ?>"><?= csrfField() ?><label class="sr-only" for="comment_text">Add a comment</label><textarea id="comment_text" name="comment_text" rows="3" maxlength="1000" required placeholder="Leave a kind note or serving tip..."></textarea><button class="button button-small" type="submit">Post note</button></form><?php else: ?><p class="login-prompt"><a href="<?= BASE_URL ?>/login.php">Log in</a> to leave a neighbor note.</p><?php endif; ?><div class="comment-list"><?php foreach ($comments as $comment): ?><article class="comment"><div class="comment-top"><strong><?= e($comment['author_name']) ?></strong><small><?= date('M j, Y', strtotime($comment['created_at'])) ?><?php if ($comment['updated_at'] > $comment['created_at']): ?> · edited<?php endif; ?></small></div><p><?= nl2br(e($comment['comment_text'])) ?></p><?php if (Auth::check() && (int) $comment['user_id'] === Auth::id()): ?><div class="comment-actions"><a href="<?= BASE_URL ?>/comment_edit.php?id=<?= (int) $comment['id'] ?>">Edit</a><form method="post" action="<?= BASE_URL ?>/comment_delete.php" data-confirm="Delete this note?"><?= csrfField() ?><input type="hidden" name="id" value="<?= (int) $comment['id'] ?>"><input type="hidden" name="recipe_id" value="<?= $id ?>"><button type="submit">Delete</button></form></div><?php endif; ?></article><?php endforeach; ?><?php if (!$comments): ?><p class="muted">No notes yet. Be the first to leave one.</p><?php endif; ?></div></aside></section>
<?php require __DIR__ . '/includes/footer.php'; ?>
